61: function queryString(params: Record<string, unknown> = {}): string {
62:   const q = new URLSearchParams()
63:   Object.entries(params).forEach(([k, v]) => {
64:     if (v !== undefined && v !== null && v !== '') q.set(k, String(v))
65:   })
66:   const s = q.toString()
67:   return s ? `?${s}` : ''
68: }
