70: /** 统一解包分页响应：兼容根级 PageResult 与 {code,msg,data} 两种包裹 */
71: async function page<T>(path: string, params: Record<string, unknown> = {}): Promise<PageResult<T>> {
72:   const body = await request<unknown>(`${path}${queryString(params)}`, { raw: true })
73:   const b = (body ?? {}) as {
74:     total?: number | string; rows?: T[]
75:     data?: { total?: number | string; rows?: T[] }
76:     code?: number; msg?: string
77:   }
78:   if (b.code !== undefined && b.code !== 200 && b.code !== 0) throw new Error(b.msg || `接口异常（code ${b.code}）`)
79:   const src = b.data && !Array.isArray(b.rows) ? b.data : b
80:   return { total: Number(src?.total ?? 0) || 0, rows: Array.isArray(src?.rows) ? src.rows : [] }
81: }
